"use client";

import * as React from "react";
import {
  DndContext,
  DragOverlay,
  closestCenter,
  pointerWithin,
  rectIntersection,
  type CollisionDetection,
} from "@dnd-kit/core";
import { cn } from "@/lib/utils";
import { DataViewToolbar } from "../data-view-criteria/data-view-toolbar";
import { KanbanColumn } from "./kanban-column";
import { KanbanSkeleton } from "./kanban-skeleton";
import type {
  DataKanbanCriteriaProps,
  KanbanColumnDefinition,
} from "@/types/use-criteria-kanban.type";
import "./styles.css";

/**
 * Custom collision detection that combines pointerWithin and rectIntersection
 * for better drop targeting, especially when dragging over columns
 */
const customCollisionDetection: CollisionDetection = (args) => {
  // First, try pointerWithin for precise pointer-based detection
  const pointerCollisions = pointerWithin(args);
  if (pointerCollisions.length > 0) {
    return pointerCollisions;
  }

  // Fall back to rectIntersection for broader detection
  const rectCollisions = rectIntersection(args);
  if (rectCollisions.length > 0) {
    return rectCollisions;
  }

  // Finally, use closestCenter as a last resort
  return closestCenter(args);
};

/**
 * Main Kanban board component with Criteria integration
 *
 * Provides a full-featured Kanban board with:
 * - Drag and drop cards between columns
 * - Optimistic updates for smooth UX
 * - Virtualized column content for performance
 * - Filter and search integration
 * - Customizable column headers, footers, and cards
 *
 * @example
 * ```tsx
 * const columns: KanbanColumnDefinition<Task>[] = [
 *   { id: 'todo', title: 'To Do', criteria: c => c.where('status', 'equals', 'todo') },
 *   { id: 'doing', title: 'Doing', criteria: c => c.where('status', 'equals', 'doing') },
 *   { id: 'done', title: 'Done', criteria: c => c.where('status', 'equals', 'done') },
 * ];
 *
 * const kanban = useCriteriaKanban<Task>('tasks', fetchTasks, {
 *   columns,
 *   getItemId: (item) => item.id,
 *   groupField: 'status',
 *   onCardMove: async ({ cardId, toColumn }) => {
 *     await api.updateTask(cardId, { status: toColumn.id });
 *   },
 * });
 *
 * <DataKanbanCriteria
 *   kanban={kanban}
 *   renderCard={(task, isDragging) => (
 *     <TaskCard task={task} isDragging={isDragging} />
 *   )}
 * />
 * ```
 */
function DataKanbanCriteria<T>({
  kanban,
  renderCard,
  renderColumnHeader,
  renderColumnFooter,
  toolbarLayout = "default",
  actionBar,
  className,
  columnsClassName,
  columnClassName,
  estimatedCardHeight = 120,
  showItemCount = true,
  showSkeleton = true,
  onCardClick,
  columnsContentScrollClassName: columnsContentScrollClassName,
  renderEmptyState,
}: DataKanbanCriteriaProps<T>) {
  const {
    columns,
    filterProps,
    searchProps,
    dndContextProps,
    sensors,
    activeItem,
    activeId,
    isLoading,
  } = kanban;

  const getItemId = React.useCallback(
    (item: T): string => {
      for (const col of columns) {
        const foundIndex = col.items.indexOf(item);
        if (foundIndex !== -1) {
          const itemObj = item as Record<string, unknown>;
          if (typeof itemObj.id === "string") return itemObj.id;
          if (typeof itemObj.id === "number") return String(itemObj.id);
          if (typeof itemObj._id === "string") return itemObj._id;
          if (typeof itemObj._id === "number") return String(itemObj._id);
        }
      }
      const itemObj = item as Record<string, unknown>;
      if (typeof itemObj.id === "string") return itemObj.id;
      if (typeof itemObj.id === "number") return String(itemObj.id);
      if (typeof itemObj._id === "string") return itemObj._id;
      return String(itemObj);
    },
    [columns]
  );

  const showToolbar = toolbarLayout !== "none";

  const boardContent = (
    <>
      {isLoading && showSkeleton && (
        <KanbanSkeleton
          columnCount={columns.length}
          cardCount={6}
        />
      )}

      {!isLoading && (
        <div
          data-slot="kanban-columns"
          className={cn(
            "flex gap-4 overflow-x-auto pb-4 kanban-scrollbar-horizontal",
            "scrollbar-thin scrollbar-track-transparent scrollbar-thumb-border",
            columnsClassName
          )}
        >
          {columns.map((columnData) => (
            <div
              key={columnData.column.id}
              className="w-80 min-w-80 shrink-0"
            >
              <KanbanColumn
                columnData={columnData}
                getItemId={getItemId}
                renderCard={renderCard}
                renderHeader={renderColumnHeader}
                renderFooter={renderColumnFooter}
                className={columnClassName}
                estimatedCardHeight={estimatedCardHeight}
                showItemCount={showItemCount}
                activeId={activeId}
                onCardClick={onCardClick}
                columnsContentScrollClassName={columnsContentScrollClassName}
                renderEmptyState={renderEmptyState ? () => renderEmptyState(columnData.column) : undefined}
              />
            </div>
          ))}
        </div>
      )}

      <DragOverlay dropAnimation={null}>
        {activeItem ? (
          renderCard(activeItem, true)
        ) : null}
      </DragOverlay>
    </>
  );

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={customCollisionDetection}
      {...dndContextProps}
    >
      <div data-slot="kanban" className={cn("flex flex-col gap-4", className)}>
        {showToolbar && (
          <DataViewToolbar
            searchProps={searchProps}
            searchPlaceholder="Search cards..."
            filterProps={filterProps}
            actionBar={actionBar}
          />
        )}

        {boardContent}
      </div>
    </DndContext>
  );
}

/**
 * Props interface exported for consumers who need type info
 */
export type { DataKanbanCriteriaProps, KanbanColumnDefinition };

export { DataKanbanCriteria };

"use client";

import * as React from "react";
import { useDroppable } from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { cn } from "@/lib/utils";
import { KanbanColumnContent } from "./kanban-column-content";
import type { KanbanColumnProps } from "@/types/use-criteria-kanban.type";

/**
 * Kanban column component with droppable area and sortable context
 *
 * Renders a single column of the Kanban board with:
 * - Droppable area for cards from other columns
 * - SortableContext for card reordering within the column
 * - Virtualized content for performance with large lists
 * - Customizable header, footer, and empty states
 *
 * @example
 * ```tsx
 * <KanbanColumn
 *   columnData={columnData}
 *   getItemId={(item) => item.id}
 *   renderCard={(item, isDragging) => (
 *     <TaskCard task={item} isDragging={isDragging} />
 *   )}
 *   estimatedCardHeight={120}
 * />
 * ```
 */
function KanbanColumn<T>({
  columnData,
  getItemId,
  renderCard,
  renderHeader,
  renderFooter,
  className,
  estimatedCardHeight,
  showItemCount = true,
  activeId,
  onCardClick,
  columnsContentScrollClassName,
  renderEmptyState,
}: KanbanColumnProps<T>) {
  const {
    column,
    items,
    totalCount,
    isLoading,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
  } = columnData;
  const containerRef = React.useRef<HTMLDivElement>(null);

  const { setNodeRef, isOver } = useDroppable({
    id: column.id,
  });

  const itemIds = React.useMemo(
    () => items.map((item) => getItemId(item)),
    [items, getItemId]
  );

  const defaultHeader = (
    <KanbanColumnHeader>
      <KanbanColumnTitle
        style={column.color ? { borderLeftColor: column.color } : undefined}
        className={column.color ? "border-l-4 pl-2" : undefined}
      >
        {column.icon && <span className="mr-2">{column.icon}</span>}
        {column.title}
      </KanbanColumnTitle>
      {showItemCount && (
        <KanbanColumnCounter>
          {totalCount}
          {column.limit && ` / ${column.limit}`}
        </KanbanColumnCounter>
      )}
    </KanbanColumnHeader>
  );


  return (
    <div
      ref={setNodeRef}
      data-slot="kanban-column"
      data-column-id={column.id}
      data-over={isOver || undefined}
      className={cn(
        "flex flex-col rounded-lg border bg-muted/30",
        "transition-colors duration-200",
        isOver && "bg-primary/5 border-primary/30",
        className
      )}
    >
      {renderHeader ? renderHeader(column, totalCount) : defaultHeader}

      <div ref={containerRef} className="flex-1 min-h-0 overflow-hidden">
        <SortableContext items={itemIds} strategy={verticalListSortingStrategy}>
          {isLoading ? (
            <KanbanColumnSkeleton count={3} />
          )
            : (
              <KanbanColumnContent
                items={items}
                getItemId={getItemId}
                renderCard={renderCard}
                estimatedCardHeight={estimatedCardHeight}
                activeId={activeId}
                onCardClick={onCardClick}
                hasNextPage={hasNextPage}
                isFetchingNextPage={isFetchingNextPage}
                onLoadMore={fetchNextPage}
                columnsContentScrollClassName={columnsContentScrollClassName}
                renderEmptyState={renderEmptyState}
              />
            )}
        </SortableContext>
      </div>

      {renderFooter && (
        <KanbanColumnFooter>
          {renderFooter(column)}
        </KanbanColumnFooter>
      )}
    </div>
  );
}

/**
 * Header section for KanbanColumn
 */
function KanbanColumnHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-column-header"
      className={cn(
        "flex items-center justify-between gap-2 px-3 py-2 border-b bg-background/50",
        className
      )}
      {...props}
    />
  );
}

/**
 * Title element for KanbanColumn header
 */
function KanbanColumnTitle({
  className,
  ...props
}: React.ComponentProps<"h3">) {
  return (
    <h3
      data-slot="kanban-column-title"
      className={cn(
        "font-semibold text-sm flex items-center",
        className
      )}
      {...props}
    />
  );
}

/**
 * Counter badge showing item count
 */
function KanbanColumnCounter({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="kanban-column-counter"
      className={cn(
        "inline-flex items-center justify-center rounded-full",
        "bg-secondary text-secondary-foreground",
        "px-2 py-0.5 text-xs font-medium",
        className
      )}
      {...props}
    />
  );
}

/**
 * Footer section for KanbanColumn
 */
function KanbanColumnFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-column-footer"
      className={cn(
        "px-3 py-2 border-t bg-background/50",
        className
      )}
      {...props}
    />
  );
}

/**
 * Loading skeleton for column content
 */
function KanbanColumnSkeleton({ count = 3 }: { count?: number }) {
  return (
    <div className="p-2 space-y-2">
      {Array.from({ length: count }).map((_, i) => (
        <div
          key={i}
          className="bg-card rounded-lg border p-3 animate-pulse"
        >
          <div className="h-4 bg-muted rounded w-3/4 mb-2" />
          <div className="h-3 bg-muted rounded w-1/2" />
        </div>
      ))}
    </div>
  );
}

export {
  KanbanColumn,
  KanbanColumnHeader,
  KanbanColumnTitle,
  KanbanColumnCounter,
  KanbanColumnFooter,
  KanbanColumnSkeleton,
};

"use client";

import * as React from "react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useInView } from "react-intersection-observer";
import { cn } from "@/lib/utils";
import type { KanbanColumnContentProps } from "@/types/use-criteria-kanban.type";

/**
 * Virtualized content renderer for Kanban column
 *
 * Uses @tanstack/react-virtual to efficiently render large lists
 * by only rendering visible items plus a configurable overscan.
 *
 * The actively dragged item is always kept rendered to ensure
 * smooth drag interactions.
 *
 * @example
 * ```tsx
 * <KanbanColumnContent
 *   items={tasks}
 *   getItemId={(task) => task.id}
 *   renderCard={(task, isDragging) => <TaskCard task={task} />}
 *   estimatedCardHeight={120}
 *   activeId={activeId}
 * />
 * ```
 */
function KanbanColumnContent<T>({
  items,
  getItemId,
  renderCard,
  estimatedCardHeight,
  activeId,
  onCardClick,
  hasNextPage,
  isFetchingNextPage,
  columnsContentScrollClassName,
  onLoadMore,
  renderEmptyState,
}: KanbanColumnContentProps<T>) {
  const parentRef = React.useRef<HTMLDivElement>(null);
  const didDragRef = React.useRef(false);
  const prevActiveIdRef = React.useRef(activeId);

  // Infinite scroll sentinel using react-intersection-observer
  const { ref: sentinelRef, inView } = useInView({
    root: parentRef.current,
    rootMargin: "100px",
    threshold: 0.1,
  });

  React.useEffect(() => {
    if (prevActiveIdRef.current !== null && activeId === null) {
      didDragRef.current = true;
      // Reset after a short delay
      const timer = setTimeout(() => {
        didDragRef.current = false;
      }, 100);
      return () => clearTimeout(timer);
    }
    prevActiveIdRef.current = activeId;
  }, [activeId]);

  const activeIndex = React.useMemo(() => {
    if (!activeId) return -1;
    return items.findIndex((item) => getItemId(item) === String(activeId));
  }, [items, activeId, getItemId]);

  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => estimatedCardHeight + 8,
    overscan: 5,
    // Enable dynamic measurement to handle variable card heights
    measureElement: (element) => {
      // Measure the actual height of the card element
      // This will be called after the element is rendered
      return element?.getBoundingClientRect().height ?? estimatedCardHeight + 8;
    },
    rangeExtractor: (range) => {
      const { startIndex, endIndex } = range;
      const indices = new Set<number>();

      for (let i = startIndex; i <= endIndex; i++) {
        indices.add(i);
      }

      if (activeIndex >= 0) {
        indices.add(activeIndex);
      }

      return Array.from(indices).sort((a, b) => a - b);
    },
  });

  const virtualItems = virtualizer.getVirtualItems();

  // Trigger load more when sentinel comes into view
  React.useEffect(() => {
    if (inView && hasNextPage && !isFetchingNextPage && onLoadMore) {
      onLoadMore();
    }
  }, [inView, hasNextPage, isFetchingNextPage, onLoadMore]);

  const handleCardClick = React.useCallback(
    (item: T, isDragging: boolean) => {
      if (isDragging || didDragRef.current || !onCardClick) return;
      onCardClick(item);
    },
    [onCardClick]
  );

  if (items.length === 0) {
    return <Content className={columnsContentScrollClassName}>
      {renderEmptyState ? (
        renderEmptyState()
      ) : (
        <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
          <p className="text-sm">No items</p>
        </div>
      )}
    </Content>
  }

  if (items.length < 20) {
    return (
      <Content ref={parentRef} className={cn("space-y-2", columnsContentScrollClassName)}>
        {items.map((item) => {
          const itemId = getItemId(item);
          const isDragging = activeId ? String(activeId) === itemId : false;

          return (
            <div
              key={itemId}
              data-item-id={itemId}
              onClick={() => handleCardClick(item, isDragging)}
            >
              {renderCard(item, isDragging)}
            </div>
          );
        })}
        {hasNextPage && (
          <LoadMoreTrigger
            onLoadMore={onLoadMore}
            isFetchingNextPage={isFetchingNextPage}
          />
        )}
      </Content>
    );
  }

  return (
    <Content ref={parentRef} className={columnsContentScrollClassName}>
      <div
        className="relative w-full"
        style={{ height: virtualizer.getTotalSize() }}
      >
        {virtualItems.map((virtualItem) => {
          const item = items[virtualItem.index];
          const itemId = getItemId(item);
          const isDragging = activeId ? String(activeId) === itemId : false;

          return (
            <div
              key={itemId}
              ref={(element) => {
                if (element) {
                  // Measure element to get its actual height
                  // This will update the virtualizer with the real size
                  virtualizer.measureElement(element);
                }
              }}
              data-item-id={itemId}
              data-index={virtualItem.index}
              className={cn(
                "absolute top-0 left-0 w-full",
                "pb-2"
              )}
              style={{
                transform: `translateY(${virtualItem.start}px)`,
              }}
              onClick={() => handleCardClick(item, isDragging)}
            >
              {renderCard(item, isDragging)}
            </div>
          );
        })}
      </div>
      {hasNextPage && (
        <div ref={sentinelRef} className="flex justify-center py-2">
          {isFetchingNextPage && <LoadingSpinner />}
        </div>
      )}
    </Content>
  );
}

/**
 * Component that triggers loading more items when it becomes visible
 */
function LoadMoreTrigger({
  onLoadMore,
  isFetchingNextPage,
}: {
  onLoadMore?: () => void;
  isFetchingNextPage?: boolean;
}) {
  const { ref, inView } = useInView({ threshold: 0.5 });

  React.useEffect(() => {
    if (inView && onLoadMore && !isFetchingNextPage) {
      onLoadMore();
    }
  }, [inView, onLoadMore, isFetchingNextPage]);

  return (
    <div ref={ref} className="flex justify-center py-2">
      {isFetchingNextPage && <LoadingSpinner />}
    </div>
  );
}

/**
 * Simple loading spinner
 */
function LoadingSpinner() {
  return (
    <div className="flex items-center gap-2 text-xs text-muted-foreground">
      <svg
        className="animate-spin h-4 w-4"
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
        viewBox="0 0 24 24"
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        />
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
        />
      </svg>
      <span>Loading...</span>
    </div>
  );
}

function Content({ className, ...props }: React.ComponentProps<"div">) {
  return <div
    className={cn("p-2 overflow-y-auto kanban-scrollbar", className)}
    {...props}
  />
}

export { KanbanColumnContent };

"use client";

import * as React from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "@/lib/utils";
import type { KanbanCardProps } from "@/types/use-criteria-kanban.type";

/**
 * Draggable card component for Kanban board
 *
 * Uses @dnd-kit/sortable for smooth drag and drop interactions.
 * Follows the composable pattern with data-slot attributes.
 *
 * @example
 * ```tsx
 * <KanbanCard id={task.id}>
 *   <KanbanCardHeader>
 *     <KanbanCardTitle>{task.title}</KanbanCardTitle>
 *   </KanbanCardHeader>
 *   <KanbanCardContent>{task.description}</KanbanCardContent>
 * </KanbanCard>
 * ```
 */
function KanbanCard({
  id,
  isDragging = false,
  isOverlay = false,
  children,
  className,
  disabled = false,
  onClick,
}: KanbanCardProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging: isSortableDragging,
  } = useSortable({
    id,
    disabled,
  });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition: transition ?? undefined,
    opacity: isSortableDragging && !isOverlay ? 0 : 1,
  };

  const dragging = isDragging || isSortableDragging;

  const didDragRef = React.useRef(false);

  React.useEffect(() => {
    if (isSortableDragging) {
      didDragRef.current = true;
    }
  }, [isSortableDragging]);

  const handleClick = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (didDragRef.current) {
        didDragRef.current = false;
        return;
      }

      if (onClick && !disabled) {
        onClick(e);
      }
    },
    [onClick, disabled]
  );

  return (
    <div
      ref={setNodeRef}
      style={style}
      data-slot="kanban-card"
      data-dragging={dragging || undefined}
      data-overlay={isOverlay || undefined}
      className={cn(
        "bg-card text-card-foreground flex flex-col gap-2 rounded-lg border p-3 shadow-sm select-none",
        "transition-shadow duration-200",
        "hover:shadow-md",
        dragging && "shadow-lg ring-2 ring-primary/20",
        isOverlay && "rotate-3 scale-105 shadow-xl",
        disabled && "opacity-60 cursor-not-allowed",
        !disabled && "cursor-pointer",
        className
      )}
      {...attributes}
      {...listeners}
      onClick={handleClick}
    >
      {children}
    </div>
  );
}

/**
 * Header section for KanbanCard
 */
function KanbanCardHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-header"
      className={cn(
        "flex items-start justify-between gap-2",
        className
      )}
      {...props}
    />
  );
}

/**
 * Title element for KanbanCard
 */
function KanbanCardTitle({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-title"
      className={cn(
        "font-medium text-sm leading-tight line-clamp-2",
        className
      )}
      {...props}
    />
  );
}

/**
 * Description/subtitle element for KanbanCard
 */
function KanbanCardDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-description"
      className={cn(
        "text-muted-foreground text-xs line-clamp-2",
        className
      )}
      {...props}
    />
  );
}

/**
 * Action button area for KanbanCard (top-right aligned)
 */
function KanbanCardAction({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-action"
      className={cn("shrink-0", className)}
      {...props}
    />
  );
}

/**
 * Main content area for KanbanCard
 */
function KanbanCardContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-content"
      className={cn("text-sm", className)}
      {...props}
    />
  );
}

/**
 * Footer section for KanbanCard
 */
function KanbanCardFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="kanban-card-footer"
      className={cn(
        "flex items-center gap-2 pt-2 border-t text-xs text-muted-foreground",
        className
      )}
      {...props}
    />
  );
}

/**
 * Badge/tag element for KanbanCard metadata
 */
function KanbanCardBadge({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="kanban-card-badge"
      className={cn(
        "inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium",
        "bg-secondary text-secondary-foreground",
        className
      )}
      {...props}
    />
  );
}

export {
  KanbanCard,
  KanbanCardHeader,
  KanbanCardTitle,
  KanbanCardDescription,
  KanbanCardAction,
  KanbanCardContent,
  KanbanCardFooter,
  KanbanCardBadge,
};

"use client";

import { cn } from "@/lib/utils";

interface KanbanSkeletonProps {
  /**
   * Number of columns to show
   * @default 3
   */
  columnCount?: number;

  /**
   * Number of cards per column
   * @default 3
   */
  cardCount?: number;

  /**
